<?php $title='FeatureBoard — Shape what gets built'; require 'header.php'; $q=trim($_GET['q']??''); $sort=$_GET['sort']??'top'; $status=$_GET['status']??''; $where=[];$args=[];if($q){$where[]='(title LIKE ? OR description LIKE ? OR category LIKE ?)';$args=["%$q%","%$q%","%$q%"];}if($status){$where[]='status=?';$args[]=$status;} $order=$sort==='new'?'created_at DESC':($sort==='discussed'?'(SELECT COUNT(*) FROM comments c WHERE c.feature_id=features.id) DESC':'votes DESC, created_at DESC');$sql='SELECT * FROM features'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY '.$order; $st=db()->prepare($sql);$st->execute($args);$features=$st->fetchAll();$flash=getflash(); ?>
<section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">Customer-powered product feedback</div><h1>Tell us what to build next.</h1><p>Submit ideas, rally votes, join the conversation, and follow every request from first suggestion to shipped feature.</p><div class="actions"><a class="btn orange" href="#submit">+ Submit a feature</a><a class="btn ghost" href="roadmap.php">See the roadmap</a></div></div><div class="hero-card"><div class="mini">THIS MONTH · COMMUNITY SIGNAL</div><h3>“Export feedback to CSV”</h3><p>One of the most requested workflow improvements is now live.</p><div class="bar"><i></i></div><div class="stats"><div><strong>73</strong><span>votes</span></div><div><strong>Shipped</strong><span>status</span></div></div></div></div></section>
